Description:
通知来电消息，如果应用来电消息建立失败，需调用 reportIncomingCallError 通知来电建立失败。需设置通话详细信息，见 VoipCallAttribute 。使用Promise异步回调。




Example:
import{image}from'@kit.ImageKit';
import{voipCall}from'@kit.CallServiceKit';
import{resourceManager}from'@kit.LocalizationKit';
import{hilog}from'@kit.PerformanceAnalysisKit';
import{UIAbility}from'@kit.AbilityKit';
import{pushService}from'@kit.PushKit';

interfaceContent{
data:string;
callId:string;
}

export default classVoipAbilityextendsUIAbility{
onCreate():void{
hilog.info(0x0000,'testTag','VoipExtAbility onCreate.');
pushService.receiveMessage('VoIP',this,async(data)=>{
      letcontent:Content=JSON.parse(data.data);
      letcallId:string=content.callId;

hilog.info(0x0000,'testTag','Get voip message successfully: %{public}s',callId);

//此处为用户头像，需要创建PixelMap类型
      constresourceMgr:resourceManager.ResourceManager=this.context.resourceManager;
      constfileData:Uint8Array=awaitresourceMgr.getRawFileContent('example.png');
      constbuffer=fileData.buffer;
      constimageSource:image.ImageSource=image.createImageSource(buffer);
      constpixelMap:image.PixelMap=awaitimageSource.createPixelMap();
      if(pixelMap){
pixelMap.getImageInfo((err,imageInfo)=>{
          if(imageInfo){
hilog.info(0x0000,'testTag',`DemoPushMessageAbility imageInfo:${imageInfo.size.width}*${imageInfo.size.height}.`);
}
});
}

//构建通话详细信息的对象
      letcallInfo:voipCall.VoipCallAttribute={
callId:callId,
voipCallType:voipCall.VoipCallType.VOIP_CALL_VOICE,
userName:"name",
userProfile:pixelMap,
abilityName:'ability',
voipCallState:voipCall.VoipCallState.VOIP_CALL_STATE_RINGING
};

//通知来电消息
      leterror=awaitvoipCall.reportIncomingCall(callInfo);
      if(error!=voipCall.ErrorReason.ERROR_NONE){
hilog.error(0x0000,'testTag','Failed to report incoming call: %{public}d',error);
        return;
}

hilog.info(0x0000,'testTag','Get voip message end.');
});
hilog.info(0x0000,'testTag','Succeeded in registering VoIP.');
}
}

