Description:
创建SpeechRecognitionEngine实例，并初始化引擎。使用callback异步回调。




Example:
import { BusinessError } from '@kit.BasicServicesKit';
import { speechRecognizer } from '@kit.CoreSpeechKit';

let asrEngine: speechRecognizer.SpeechRecognitionEngine;

// 设置创建引擎参数
