import{AdComponent,advertising}from'@kit.AdsKit';
import{hilog}from'@kit.PerformanceAnalysisKit';

@Entry
@Component
structShowNonFullScreenAd{
// 请求到的广告内容
privateads:Array<advertising.Advertisement> = [];
