Module: @ohos.animator (动画)
Import: import { Animator as animator, AnimatorOptions,AnimatorResult } from '@kit.ArkUI';
Overview: 本模块提供组件动画效果，包括定义动画、启动动画和以相反的顺序播放动画等。

Module: @ohos.animator (动画)
Item: reset
Type: method
Import: import { Animator as animator, AnimatorOptions,AnimatorResult } from '@kit.ArkUI';
Signature: reset(options: AnimatorOptions): void

Description:
更新当前动画器。




Example:
import { Animator as animator, AnimatorOptions, AnimatorResult } from '@kit.ArkUI';
import { BusinessError } from '@kit.BasicServicesKit';

let options: AnimatorOptions = {
  duration: 1500,
  easing: "friction",
  delay: 0,
  fill: "forwards",
  direction: "normal",
  iterations: 3,
  begin: 200.0,
  end: 400.0
};
let optionsNew: AnimatorOptions = {
  duration: 1500,
  easing: "friction",
  delay: 0,
  fill: "forwards",
  direction: "normal",
  iterations: 5,
  begin: 200.0,
  end: 400.0
};
try {
  let animatorResult: AnimatorResult | undefined = animator.create(options)
  animatorResult.reset(optionsNew);
} catch (error) {
  let message = (error as BusinessError).message
  let code = (error as BusinessError).code
  console.error(`Animator reset failed, error code: ${code}, message: ${message}.`);
}

