Module: @ohos.app.ability.autoFillManager (autoFillManager)
Item: autoFillManager.requestAutoSave
Type: method
Import: import { autoFillManager } from '@kit.AbilityKit';
Signature: requestAutoSave(context: UIContext, callback?: AutoSaveCallback): void

Description:
请求保存表单数据，使用callback异步回调。 如果当前表单没有提供表单切换的功能，可以通过此接口保存历史表单输入数据，保存请求完成时会触发该回调。




Example:
// EntryAbility.ets
import { UIAbility, common } from '@kit.AbilityKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { window, UIContext } from '@kit.ArkUI';
import { hilog } from '@kit.PerformanceAnalysisKit';

export default class EntryAbility extends UIAbility {
onWindowStageCreate(windowStage: window.WindowStage): void {
  // Main window is created, set main page for this ability
  hilog.info(0x0000, 'testTag', '%{public}s', 'Ability onWindowStageCreate');
  let localStorageData: Record<string, string | common.UIAbilityContext> = {
    'message': "AutoFill Page",
    'context': this.context,
  };
  let storage = new LocalStorage(localStorageData);
  windowStage.loadContent('pages/Index', storage, (err, data) => {
    if (err.code) {
      hilog.error(0x0000, 'testTag', 'Failed to load the content. Cause: %{public}s', JSON.stringify(err) ?? '');
      return;
    }
    // Obtain the main window.
    windowStage.getMainWindow((err: BusinessError, data: window.Window) => {
      let errCode: number = err.code;
      if (errCode) {
        console.error('Failed to obtain the main window. Cause: ' + JSON.stringify(err));
        return;
      }
      console.info('Succeeded in obtaining the main window. Data: ' + JSON.stringify(data));
      // get UIContext instance.
      let uiContext: UIContext = windowStage.getMainWindowSync().getUIContext();
      PersistentStorage.persistProp("uiContext", uiContext);
    })
    hilog.info(0x0000, 'testTag', 'Succeeded in loading the content. Data: %{public}s', JSON.stringify(data) ?? '');
  });
}
}

