Type: method
Import: import { distributedDataObject } from '@kit.ArkData';
Signature: on(type: 'change', callback: (sessionId: string, fields: Array<string>) => void): void

Description:
监听分布式数据对象的变更。




Example:
class SourceObject {
    name: string
    age: number
    isVis: boolean

    constructor(name: string, age: number, isVis: boolean) {
        this.name = name
        this.age = age
        this.isVis = isVis
    }
}

