Module: @ohos.file.fs (文件管理)
Item: fs.copy
Type: method
Import: import { fileIo as fs } from '@kit.CoreFileKit';
Signature: copy(srcUri: string, destUri: string, options?: CopyOptions): Promise<void>

Description:
拷贝文件或者目录，使用Promise异步返回。 支持跨设备拷贝。强制覆盖拷贝。入参支持文件或目录URI。\n 跨端拷贝时，限制同时最多存在10个拷贝任务；单次拷贝的文件数量不得超过500个。




Example:
import { fileIo as fs } from '@kit.CoreFileKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { fileUri } from '@kit.CoreFileKit';

let srcDirPathLocal: string = pathDir + "/src";
let dstDirPathLocal: string = pathDir + "/dest";

let srcDirUriLocal: string = fileUri.getUriFromPath(srcDirPathLocal);
let dstDirUriLocal: string = fileUri.getUriFromPath(dstDirPathLocal);

let progressListener: fs.ProgressListener = (progress: fs.Progress) => {
  console.info(`progressSize: ${progress.processedSize}, totalSize: ${progress.totalSize}`);
};
let copyoption: fs.CopyOptions = {
  "progressListener" : progressListener
}
try {
  fs.copy(srcDirUriLocal, dstDirUriLocal, copyoption).then(()=>{
    console.info("Succeeded in copying. ");
  }).catch((err: BusinessError)=>{
    console.error(`Failed to copy: ${JSON.stringify(err)}`);
  })
} catch(err) {
  console.error(`Failed to copy: ${JSON.stringify(err)}`);
}

