Module: @ohos.file.hash (文件哈希处理)
Import: import { hash } from '@kit.CoreFileKit';
Overview: 该模块提供文件哈希处理能力，对文件内容进行哈希处理。

Module: @ohos.file.hash (文件哈希处理)
Item: hash.createHash
Type: method
Import: import { hash } from '@kit.CoreFileKit';
Signature: createHash(algorithm: string): HashStream;

Description:
创建并返回 HashStream 对象，该对象可用于使用给定的 algorithm 生成哈希摘要。




Example:
// pages/xxx.ets
import { fileIo as fs } from '@kit.CoreFileKit';

function hashFileWithStream() {
  const filePath = pathDir + "/test.txt";
  // 创建文件可读流
  const rs = fs.createReadStream(filePath);
  // 创建哈希流
  const hs = hash.createHash('sha256');
  rs.on('data', (emitData) => {
    const data = emitData?.data;
    hs.update(new Uint8Array(data?.split('').map((x: string) => x.charCodeAt(0))).buffer);
  });
  rs.on('close', async () => {
    const hashResult = hs.digest();
    const fileHash = await hash.hash(filePath, 'sha256');
    console.info(`hashResult: ${hashResult}, fileHash: ${fileHash}`);
  });
}

