Module: SoundPool (音频池)
Item: load
Type: method
Import: import { media } from '@kit.MediaKit';
import { audio } from '@kit.AudioKit';
Signature: load(uri: string, callback: AsyncCallback<number>): void

Description:
加载音频资源。使用callback方式异步获取资源ID，入参uri通过获取文件fd生成以"fd://"开头的文件描述字符串。 该方法不支持加载rawfile目录资源，需要通过 load(fd: number, offset: number, length: number, callback: AsyncCallback<number>): void 或者 load(fd: number, offset: number, length: number): Promise<number> 实现。




Example:
import { fileIo } from '@kit.CoreFileKit';
import { BusinessError } from '@kit.BasicServicesKit';

//创建soundPool实例。
let soundPool: media.SoundPool;
let audioRendererInfo: audio.AudioRendererInfo = {
  usage: audio.StreamUsage.STREAM_USAGE_MUSIC,
  rendererFlags: 1
}
media.createSoundPool(5, audioRendererInfo, (error: BusinessError, soundPool_: media.SoundPool) => {
  if (error) {
    console.error(`Failed to createSoundPool`)
    return;
  } else {
    soundPool = soundPool_;
    console.info(`Succeeded in createSoundPool`)
    let uri:string = "";
    let file: fileIo.File;
    //获取fd的uri路径。
    fileIo.open('/test_01.mp3', fileIo.OpenMode.READ_ONLY).then((file_: fileIo.File) => {
      file = file_;
      console.info("file fd: " + file.fd);
      uri = 'fd://' + (file.fd).toString()
      soundPool.load(uri, (error: BusinessError, soundId_: number) => {
        if (error) {
          console.error(`Failed to load soundPool: errCode is ${error.code}, errMessage is ${error.message}`)
        } else {
          console.info(`Succeeded in loading soundPool` + JSON.stringify(soundId_))
        }
      });
    }); // '/test_01.mp3' 作为样例，使用时需要传入文件对应路径。
  }
});

