Signature: play(soundID: number, params: PlayParameters, callback: AsyncCallback<number>): void

Description:
播放音频资源。使用callback方式异步获取音频流streamID。




Example:
import { BusinessError } from '@kit.BasicServicesKit';

//创建soundPool实例。
