      rightVolume: 0.5, // range = 0.0-1.0
      priority: 0, // 最低优先级。
    }
    soundPool.play(soundID, playParameters, (error: BusinessError, streamId: number) => {
      if (error) {
        console.error(`Failed to play soundpool: errCode is ${error.code}, errMessage is ${error.message}`)
      } else {
        streamID = streamId;
