Module: @ohos.InputMethodExtensionContext (InputMethodExtensionContext)
Item: InputMethodExtensionContext.startAbility
Type: method
Import: import { InputMethodExtensionContext } from '@kit.IMEKit';
Signature: startAbility(want: Want): Promise<void>;

Description:
拉起目标应用。使用Promise异步回调。




Example:
import { InputMethodExtensionAbility } from '@kit.IMEKit';
import { Want } from '@kit.AbilityKit';
import { BusinessError } from '@kit.BasicServicesKit';

class InputMethodExtnAbility extends InputMethodExtensionAbility {
  onCreate(want: Want): void {
    let context = this.context;
  }
  onDestroy() {
    let want: Want = {
      bundleName: "com.example.aafwk.test",
      abilityName: "com.example.aafwk.test.TwoAbility"
    };
    try {
      this.context.startAbility(want).then(() => {
        console.log(`startAbility success`);
      }).catch((err: BusinessError) => {
        let error = err as BusinessError;
        console.log(`startAbility error: ${error.code} ${error.message}`);
      })
    } catch (err) {
      let error = err as BusinessError;
      console.log(`startAbility error: ${error.code} ${error.message}`);
    }
  }
}

