Module: @ohos.util.LightWeightMap (非线性容器LightWeightMap)
Item: [Symbol.iterator]
Type: method
Import: import { LightWeightMap } from '@kit.ArkTS';
Signature: [Symbol.iterator](): IterableIterator<[K, V]>

Description:
返回一个迭代器，迭代器的每一项都是一个JavaScript对象，并返回该对象。




Example:
let lightWeightMap: LightWeightMap<string, number> = new LightWeightMap();
lightWeightMap.set("squirrel", 123);
lightWeightMap.set("sparrow", 356);

// 使用方法一：
let nums = Array.from(lightWeightMap.values());
for (let item1 of nums) {
  console.log("value:" + item1);
}

let key = Array.from(lightWeightMap.keys());
for (let item2 of key) {
  console.log("key:" + item2);
}

// 使用方法二：
let iter = lightWeightMap[Symbol.iterator]();
let temp: IteratorResult<Object[]> = iter.next();
while(!temp.done) {
  console.log("key:" + temp.value[0]);
  console.log("value:" + temp.value[1]);
  temp = iter.next();
}

