Module: @ohos.multimedia.media (媒体服务)
Item: MediaDescription
Type: other
Import: import { media } from '@kit.MediaKit';
Signature: 

Description:
通过key-value方式获取媒体信息。


Table Details:
名称 | 类型 | 必填 | 说明
----------------------------------------
[key: string] | Object | 是 | 该键值对支持的key取值范围，请参考 MediaDescriptionKey ;每个key值的Object类型和范围，请参考 MediaDescriptionKey 对应Key值的说明



Example:
import { BusinessError } from '@kit.BasicServicesKit';

function printfItemDescription(obj: media.MediaDescription, key: string) {
  let property: Object = obj[key];
  console.info('audio key is ' + key); // 通过key值获取对应的value。key值具体可见[MediaDescriptionKey]。
  console.info('audio value is ' + property); //对应key值得value。其类型可为任意类型，具体key对应value的类型可参考[MediaDescriptionKey]。
}

let avPlayer: media.AVPlayer | undefined = undefined;
media.createAVPlayer((err: BusinessError, player: media.AVPlayer) => {
  if(player != null) {
    avPlayer = player;
    console.info(`Succeeded in creating AVPlayer`);
    avPlayer.getTrackDescription((error: BusinessError, arrList: Array<media.MediaDescription>) => {
      if (arrList != null) {
        for (let i = 0; i < arrList.length; i++) {
          printfItemDescription(arrList[i], media.MediaDescriptionKey.MD_KEY_TRACK_TYPE);  //打印出每条轨道MD_KEY_TRACK_TYPE的值。
        }
      } else {
        console.error(`Failed to get TrackDescription, error:${error}`);
      }
    });
  } else {
    console.error(`Failed to create AVPlayer, error message:${err.message}`);
  }
});

