Item: connection.setAppNet
Type: method
Import: import { connection } from '@kit.NetworkKit';
Signature: setAppNet(netHandle: NetHandle, callback: AsyncCallback<void>): void

Description:
绑定App到指定网络，绑定后的App只能通过指定网络访问外网，使用callback方式作为异步方法。




Example:
import { connection } from '@kit.NetworkKit';
import { BusinessError } from '@kit.BasicServicesKit';

connection.getDefaultNet((error: BusinessError, netHandle: connection.NetHandle) => {
  if (netHandle.netId == 0) {
    // 当前没有已连接的网络时，获取的netHandler的netid为0，属于异常场景，此处可以实际情况自行添加一些处理机制。
    return;
  }
  connection.setAppNet(netHandle, (error: BusinessError, data: void) => {
    if (error) {
      console.error(`Failed to get default net. Code:${error.code}, message:${error.message}`);
      return;
    }
    console.info("Succeeded to get data: " + JSON.stringify(data));
  });
});

