Signature: requestEnableNotification(context: UIAbilityContext, callback: AsyncCallback<void>): void

Description:
应用请求通知使能模态弹窗。使用callback异步回调。 仅当应用界面加载完成后（即调用 loadContent 成功），方可使用该接口。




Example:
import { BusinessError } from '@kit.BasicServicesKit';
import { UIAbility } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';
