Module: @ohos.request (上传下载)
Item: request.uploadFile
Type: method
Import: import { request } from '@kit.BasicServicesKit';
Signature: uploadFile(context: BaseContext, config: UploadConfig): Promise<UploadTask>

Description:
上传，异步方法，使用promise形式返回结果，支持HTTP协议。通过 on('complete'|'fail') 9+ 可获取任务上传时的错误信息。




Example:
import { BusinessError } from '@kit.BasicServicesKit';

let uploadTask: request.UploadTask;
let uploadConfig: request.UploadConfig = {
  url: 'http://www.example.com', // 需要手动将url替换为真实服务器的HTTP协议地址
  header: { 'Accept': '*/*' },
  method: "POST",
  files: [{ filename: "test", name: "test", uri: "internal://cache/test.jpg", type: "image/jpeg" }], // 建议type填写HTTP协议规范的MIME类型
  data: [{ name: "name123", value: "123" }],
};
try {
  request.uploadFile(getContext(), uploadConfig).then((data: request.UploadTask) => {
    uploadTask = data;
  }).catch((err: BusinessError) => {
    console.error(`Failed to request the upload. Code: ${err.code}, message: ${err.message}`);
  });
} catch (err) {
  console.error(`Failed to request the upload. err: ${JSON.stringify(err)}`);
}

