Module: @ohos.request (上传下载)
Item: request.agent.create
Type: method
Import: import { request } from '@kit.BasicServicesKit';
Signature: create(context: BaseContext, config: Config, callback: AsyncCallback<Task>): void

Description:
创建要上传或下载的任务，并将其排入队列。支持HTTP协议，使用callback异步回调。




Example:
import { BusinessError } from '@kit.BasicServicesKit';

let attachments: Array<request.agent.FormItem> = [{
  name: "createTest",
  value: {
    filename: "createTest.avi",
    mimeType: "application/octet-stream",
    path: "./createTest.avi",
  }
}];
let config: request.agent.Config = {
  action: request.agent.Action.UPLOAD,
  url: 'http://127.0.0.1', // 需要手动将url替换为真实服务器的HTTP协议地址
  title: 'createTest',
  description: 'Sample code for create task',
  mode: request.agent.Mode.BACKGROUND,
  overwrite: false,
  method: "PUT",
  data: attachments,
  saveas: "./",
  network: request.agent.Network.CELLULAR,
  metered: false,
  roaming: true,
  retry: true,
  redirect: true,
  index: 0,
  begins: 0,
  ends: -1,
  gauge: false,
  precise: false,
  token: "it is a secret"
};
request.agent.create(getContext(), config, async (err: BusinessError, task: request.agent.Task) => {
  if (err) {
    console.error(`Failed to create a download task, Code: ${err.code}, message: ${err.message}`);
    return;
  }
  console.info(`Succeeded in creating a download task. result: ${task.config}`);
  await task.start();
  //用户需要手动调用remove从而结束task对象的生命周期
  request.agent.remove(task.tid);
});

