try {
  data.writeRemoteObject(testRemoteObject);
} catch (error) {
  let e: BusinessError = error as BusinessError;
  hilog.error(0x0000, 'testTag', 'Rpc write remote object fail, errorCode ' + e.code);
  hilog.error(0x0000, 'testTag', 'Rpc write remote object fail, errorMessage ' + e.message);
}

Module: @ohos.rpc (RPC通信)
Item: readRemoteObject
Type: method
Import: import { rpc } from '@kit.IPCKit';
Signature: readRemoteObject(): IRemoteObject

Description:
