  }
};

Module: @ohos.window (窗口)
Item: on('windowStageClose')
Type: method
Import: import { window } from '@kit.ArkUI';
Signature: on(eventType: 'windowStageClose', callback: Callback<void>): void

Description:
开启点击主窗三键区的关闭按钮监听事件。点击主窗口的三键区域的关闭键时触发该回调函数，将不执行注册的 UIAbility.onPrepareToTerminate 生命周期回调函数。 当重复注册窗口关闭事件的监听时，最后一次注册成功的监听事件生效。 触发的回调函数是同步执行，主窗口的异步关闭事件监听参考 on('windowWillClose') 方法。 如果存在 on('windowWillClose') 监听事件，只响应 on('windowWillClose') 接口。 此接口仅可在2in1设备或平板设备的自由多窗模式（可点击设备控制中心中的自由多窗按钮开启）下使用。




Example:
// EntryAbility.ets
import { UIAbility } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';

export default class EntryAbility extends UIAbility {
  // ...

  onWindowStageCreate(windowStage: window.WindowStage) {
    console.info('onWindowStageCreate');
    try {
      windowStage.on('windowStageClose', () => {
        console.info('Succeeded in enabling the listener for window stage close event.');
        return false;
      });
    } catch (exception) {
      console.error(`Failed to enable the listener for window stage close event. Cause code: ${exception.code}, message: ${exception.message}`);
    }
  }
};

