          .type(ButtonType.Capsule)
          .height(60)
          .width(200)
          .onClick(() => {
            let context = getContext(this);
            let pathDir = context.cacheDir;
            gzgetsDemo(pathDir);
          })
      }
      .width('100%')
    }
    .height('100%')
  }
}

