  let page: pdfService.PdfPage = pdfDocument.getPage(0);
  let annotations: Array<pdfService.PdfAnnotation> = page.getAnnotations();
  let annot: pdfService.PdfAnnotation = annotations[0]; // 获取当前页的批注
