import { fileIo } from '@kit.CoreFileKit';
import { BusinessError } from '@kit.BasicServicesKit';
// 此路径为沙箱路径，test-example.txt为示例，请根据实际情况自定义文件名
const downloadedPath = `${getContext().filesDir}` + '/test-example.txt';

const session = rcp.createSession();
if (fileIo.accessSync(downloadedPath)) {
  fileIo.unlinkSync(downloadedPath);
}

const rcpDownloadToFile: rcp.DownloadToFile = {
  kind: 'file',
  file: downloadedPath
}
session.downloadToFile(`https://www.example.com`, rcpDownloadToFile).then((resp: rcp.Response) => {
  console.info(`The resource is downloaded successfully. The path is ${JSON.stringify(resp.downloadedTo)}`)
}).catch((err: BusinessError) => {
  console.error(`Failed to download the resource. Error is ${JSON.stringify(err)}`)
})

