  "byteBuffer": buffer,
  "scanCodeRects": [{
    "left": 84,
    "top": 142,
    "right": 1695,
    "bottom": 996
  }]
};
if (frameResult && frameResult.scanCodeRects) {
  let rect: scanBarcode.ScanCodeRect = frameResult.scanCodeRects[0];
