  verifyToken?: string;
}

@Entry
@Component
struct SecondPage {

  obtainRealNameDataInfo(authCode: string, sceneID:number, openID: string, realName: string, idNo: string,
    callback: AsyncCallback<Result>) {
    // Each httpRequest corresponds to an HTTP request task and cannot be reused.
    let httpRequest = http.createHttp();
    // Listen for the HTTP Response Header event, which is returned earlier than the response to the HTTP request. It is up to you whether to listen for HTTP Response Header events.
    httpRequest.on('headersReceive', (header) => {
      hilog.info(0x0000, "testTag", "header: %{public}s", header as string);
    });
    httpRequest.request(
      // Customize EXAMPLE_URL in extraData on your own. It is up to you whether to add parameters to the URL.
      "EXAMPLE_URL",
      {
        method: http.RequestMethod.POST,
        // You can add header fields based on service requirements.
        header: {
          'Content-Type': 'application/json'
        },
        // Use this field to transfer information in a POST request.
        extraData: {
          "authCode": authCode,
          "sceneID": sceneID,
          "openID": openID,
          "realname": realName,
          "idNo": idNo,
        },
        expectDataType: http.HttpDataType.STRING,
        usingCache: true,
        priority: 1,
        connectTimeout: 60000,
        readTimeout: 60000,
        usingProtocol: http.HttpProtocol.HTTP1_1,
      }, (err, data) => {
      if (!err) {
        let res: Result = JSON.parse(data.result as string);
        callback(undefined, res);
      } else {
        let error: BusinessError = {code: err.code, message: err.message, name: ''};
        callback(error, undefined);
        // Unsubscribe from HTTP Response Header events.
        httpRequest.off('headersReceive');
        // Call the destroy() method to release resources after httpRequest is complete.
        httpRequest.destroy();
      }
    })
  }

  build() {
