Module: devicePicker (设备选择控制器)
Item: release
Type: method
Import: import { devicePicker } from '@kit.ServiceCollaborationKit'
Signature: release(): void

Description:
释放设备选择控制器，与 createDevicePickerController 方法对应 。 在应用不需要设备选择控制器的时候需要调用release()接口进行释放，比如在应用onCreate()生命周期回调中通过 createDevicePickerController 创建了设备选择控制器，可以在 onDestroy()生命周期回调中通过release()进行释放。




Example:
import { hilog } from '@kit.PerformanceAnalysisKit'
import { UIAbility, AbilityConstant, Want } from '@kit.AbilityKit'
import { devicePicker } from '@kit.ServiceCollaborationKit'

export default class EntryAbility extends UIAbility {
  // 创建设备选择控制器
  controller: devicePicker.DevicePickerController = devicePicker.createDevicePickerController()

  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam) {
    hilog.info(0x0000, 'testTag', '%{public}s', 'Ability onCreate')
  }

  onDestroy() {
    hilog.info(0x0000, 'testTag', '%{public}s', 'Ability onDestroy')
    // 释放设备选择控制器
    this.controller.release()
  }
}

