Module: hdsDrawable
Item: hdsDrawable.getHdsLayeredIcon
Type: method
Import: import { hdsDrawable } from '@kit.UIDesignKit';
Signature: getHdsLayeredIcon(bundleName: string, layeredDrawableDescriptor: LayeredDrawableDescriptor, size: number, hasBorder?: boolean): image.PixelMap

Description:
获取处理后的分层图标接口。 可以通过该接口获取以PixelMap为格式的图标图片，需插入单个图标时可调用该接口。 分层图标对象以LayeredDrawableDescriptor格式定义，可以通过当传入Symbol资源的id或name生成该类对象。hasBorder决定是否为输出的Symbol描边，在线主题场景时不支持设置描边。输入的size应该和layeredDrawableDescriptor返回的PixelMap尺寸一致。 LayeredDrawableDescriptor对象：判断的方法是打开对应的Symbol json文件后观察其layered-image属性是否包含类似下面的结构：




Example:
import { LayeredDrawableDescriptor } from '@kit.ArkUI';
import { hdsDrawable } from '@kit.UIDesignKit';
import { image } from '@kit.ImageKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { resourceManager } from '@kit.LocalizationKit';

let bundleName: string = 'com.example.uidesignkit';
try {
  let resManager: resourceManager.ResourceManager = getContext().resourceManager;
  let layeredDrawableDescriptor: LayeredDrawableDescriptor =
    (resManager.getDrawableDescriptor($r('app.media.drawable')
      .id)) as LayeredDrawableDescriptor; // 传入已创建的图片资源
  let processedIcon: image.PixelMap =
    hdsDrawable.getHdsLayeredIcon(bundleName, layeredDrawableDescriptor, 48, true);
} catch (err) {
  let message = (err as BusinessError).message;
  let code = (err as BusinessError).code;
  console.error(`getHdsLayeredIcon failed, code: ${code}, message: ${message}`);
}

